using Godot;
using System;
using System.Collections.Generic;
using Settings=Godot.Collections.Dictionary;
public partial class FogPaintGizmoOperations:RefCounted
{
    private readonly FogFieldOperations _field=new();private readonly ActorDataOperations _data=new();
    private static GodotObject Spatial(RefCounted owner)=>owner.Get("spatial").AsGodotObject();private static Node? Primary(RefCounted owner)=>Spatial(owner).Call("primary").As<Node>();private static Control Canvas(RefCounted owner)=>Spatial(owner).Get("gizmo").As<Control>();private static GodotObject Model(RefCounted owner)=>Spatial(owner).Get("editor").AsGodotObject().Get("model").AsGodotObject();private Variant Value(Resource data,string key,Variant fallback)=>_data.object_get_value(data,new StringName(key),fallback);
    public bool active(RefCounted owner){var runtime=Primary(owner);if(runtime==null)return false;var actor=runtime.Get("actor").As<Resource>();if(actor.Get("type_id").AsString() is not ("fog_volume" or "global_fog")||!actor.HasMeta("editor_fog_field"))return false;var meta=actor.GetMeta("editor_fog_field");return meta.VariantType==Variant.Type.Object&&meta.AsGodotObject() is Resource resource&&ActorDataOperations.ScriptIs(resource,"res://scripts/actors/core/actor_object_data.gd")&&runtime.Get("content").AsGodotObject() is FogVolume;}
    public Resource? field(RefCounted owner)=>active(owner)?Primary(owner)!.Get("actor").As<Resource>().GetMeta("editor_fog_field").As<Resource>():null;
    public void tick(RefCounted owner){if(owner.Get("painting").AsBool()&&(!active(owner)||field(owner)!=owner.Get("object").As<Resource>()||Primary(owner)!.Get("actor").AsGodotObject()!=owner.Get("owner_actor").AsGodotObject()))finish(owner,true);}
    public Vector3 point(RefCounted owner,Vector2 screen)
    {
        var spatial=Spatial(owner);if(!active(owner)||!spatial.Call("in_picture",screen).AsBool())return Vector3.Inf;var fog=Primary(owner)!.Get("content").As<FogVolume>();var transform=fog.GlobalTransform;if(Math.Abs(transform.Basis.Determinant())<.000001)return Vector3.Inf;var inverse=transform.AffineInverse();var ray=spatial.Call("_ray",screen).AsGodotDictionary();var origin=inverse*ray["origin"].AsVector3();var direction=inverse.Basis*ray["direction"].AsVector3();var values=field(owner)!.Get("values").AsGodotDictionary();int axis=values.GetValueOrDefault("paint_plane",0).AsInt32();var normal=axis==0?(inverse.Basis*spatial.Call("camera").As<Camera3D>().GlobalBasis.Z).Normalized():new[]{Vector3.Right,Vector3.Up,Vector3.Back}[axis-1];var center=normal*(values.GetValueOrDefault("paint_depth",.5).AsSingle()-.5f)*(axis==0?fog.Size.Length():fog.Size[axis-1]);var hit=new Plane(normal,normal.Dot(center)).IntersectsRay(origin,direction);if(hit==null||!new Aabb(-fog.Size*.5f,fog.Size).HasPoint(hit.Value))return Vector3.Inf;return hit.Value/fog.Size+Vector3.One*.5f;
    }
    public void draw(RefCounted owner)
    {
        if(!active(owner))return;var spatial=Spatial(owner);var canvas=Canvas(owner);var cursor=point(owner,canvas.GetLocalMousePosition());owner.Set("cursor",cursor);if(cursor==Vector3.Inf)return;var fog=Primary(owner)!.Get("content").As<FogVolume>();var world=fog.GlobalTransform*((cursor-Vector3.One*.5f)*fog.Size);var center=spatial.Call("project",world).AsVector2();var data=field(owner)!;int axis=Value(data,"paint_plane",0).AsInt32();var normal=axis==0?(fog.GlobalTransform.Basis.Inverse()*spatial.Call("camera").As<Camera3D>().GlobalBasis.Z*fog.Size).Normalized():new[]{Vector3.Right,Vector3.Up,Vector3.Back}[axis-1];var tangent=normal.Cross(Vector3.Up).Normalized();if(tangent.LengthSquared()<.1)tangent=normal.Cross(Vector3.Right).Normalized();var bitangent=normal.Cross(tangent).Normalized();float radius=Value(data,"brush_radius",3.0).AsSingle()/32;var ring=new Vector2[65];for(int i=0;i<65;i++){float angle=Mathf.Tau*i/64;var p=cursor+(tangent*Mathf.Cos(angle)+bitangent*Mathf.Sin(angle))*radius;ring[i]=spatial.Call("project",fog.GlobalTransform*((p-Vector3.One*.5f)*fog.Size)).AsVector2();}canvas.DrawPolyline(ring,new Color("80e8cb"),2,true);canvas.DrawCircle(center,3,new Color("ffda8b"));canvas.DrawString(ThemeDB.FallbackFont,new Vector2(12,30),"3D fog paint · Ctrl subtracts · Esc cancels / exits",HorizontalAlignment.Left,-1,12,new Color("d4eee9"));
    }
    public bool handle_event(RefCounted owner,InputEvent e)
    {
        if(!active(owner))return false;bool painting=owner.Get("painting").AsBool();if(e is InputEventKey key&&key.Pressed&&key.Keycode==Key.Escape){if(painting)finish(owner,true);else Primary(owner)!.Get("actor").As<Resource>().RemoveMeta("editor_fog_field");return true;}if(e is InputEventMouseButton right&&right.ButtonIndex==MouseButton.Right){if(painting){finish(owner,true);return true;}return false;}if(e is InputEventMouseMotion motion){if(painting)dab(owner,motion.Position,motion.CtrlPressed);return painting;}if(e is InputEventMouseButton button&&button.ButtonIndex==MouseButton.Left){if(button.Pressed){if(point(owner,button.Position)==Vector3.Inf)return false;owner.Set("owner_actor",Primary(owner)!.Get("actor"));var data=field(owner)!;owner.Set("object",data);owner.Set("before",_data.copy_value(Value(data,"paint",new Settings())));owner.Set("painting",true);owner.Set("last",Vector3.Inf);Canvas(owner).GrabFocus();dab(owner,button.Position,button.CtrlPressed);}else finish(owner,false);return true;}return false;
    }
    public void dab(RefCounted owner,Vector2 screen,bool subtract)
    {
        var p=point(owner,screen);if(p==Vector3.Inf){owner.Set("last",Vector3.Inf);return;}var data=owner.Get("object").As<Resource>();double radius=Value(data,"brush_radius",3.0).AsDouble();var last=owner.Get("last").AsVector3();var from=last!=Vector3.Inf?last:p;int steps=Math.Clamp((int)Math.Ceiling(from.DistanceTo(p)*32/Math.Max(.5,radius*.25)),1,128);var voxels=Value(data,"paint",new Settings()).AsGodotDictionary();for(int i=1;i<=steps;i++){var q=(from.Lerp(p,(float)i/steps)*32).Floor();var centers=new List<Vector3I>{new((int)q.X,(int)q.Y,(int)q.Z)};for(int axis=0;axis<3;axis++){if(!Value(data,"symmetry_"+new[]{"x","y","z"}[axis],false).AsBool())continue;int count=centers.Count;for(int j=0;j<count;j++){var mirrored=centers[j];mirrored[axis]=31-mirrored[axis];centers.Add(mirrored);}}foreach(var center in centers)voxels=_field.paint_dab(voxels,center,radius,Value(data,"brush_strength",.5).AsDouble(),Value(data,"brush_falloff",1.0).AsDouble(),subtract?1:Value(data,"brush_tool",0).AsInt32());}owner.Set("last",p);_data.set_value(data,new StringName("paint"),voxels);Model(owner).EmitSignal("changed");Canvas(owner).QueueRedraw();
    }
    public void finish(RefCounted owner,bool cancel)
    {
        if(!owner.Get("painting").AsBool())return;owner.Set("painting",false);var data=owner.Get("object").As<Resource>();var after=_data.copy_value(Value(data,"paint",new Settings()));_data.set_value(data,new StringName("paint"),owner.Get("before"));if(!cancel)Model(owner).Call("edit_object_property",owner.Get("owner_actor"),data,_field.definition(),new StringName("paint"),after);else Model(owner).EmitSignal("changed");owner.Set("before",new Settings());owner.Set("object",default(Variant));owner.Set("owner_actor",default(Variant));owner.Set("last",Vector3.Inf);
    }
}
